require dirname(__DIR__).'/includes/bootstrap.php';require_permission('drivers.create');verify_csrf();$name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));$normalized=preg_replace('/\D+/','',$phone)??'';if($name===''||strlen($normalized)<7){flash('error','Driver name and a valid phone number are required.');redirect('drivers.php');}$pdo=db();$q=$pdo->prepare('SELECT id FROM drivers WHERE phone_normalized=? LIMIT 1');$q->execute([$normalized]);if($q->fetchColumn()){flash('error','Duplicate driver detected: this phone number already exists.');redirect('drivers.php');}$status=in_array($_POST['status']??'',['lead','registered','verification_pending','verified','rejected','inactive'],true)?$_POST['status']:'verification_pending';$verification=$status==='verified'?'verified':'pending';$employee=(int)($_POST['assigned_employee_id']??0)?:null;$source=trim((string)($_POST['registration_source']??''));try{transaction(function(PDO $pdo)use($name,$phone,$normalized,$status,$verification,$employee,$source){$code='DRV-'.date('ymdHis').'-'.random_int(100,999);$stmt=$pdo->prepare('INSERT INTO drivers(driver_code,full_name,phone,phone_normalized,registration_at,status,registration_source,assigned_employee_id,verification_status,verified_at,notes,created_by,updated_by) VALUES(?,?,?,?,UTC_TIMESTAMP(),?,?,?,?,?,?,?,?)');$verifiedAt=$verification==='verified'?gmdate('Y-m-d H:i:s'):null;$stmt->execute([$code,$name,$phone,$normalized,$status,$source?:null,$employee,$verification,$verifiedAt,trim((string)($_POST['notes']??''))?:null,current_user_id(),current_user_id()]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO driver_status_history(driver_id,from_status,to_status,reason,changed_by) VALUES(?,NULL,?,?,?)')->execute([$id,$status,'Created',current_user_id()]);$campaign=$pdo->query("SELECT id FROM campaigns WHERE status='active' AND CURDATE() BETWEEN start_date AND deadline ORDER BY start_date DESC LIMIT 1")->fetchColumn();if($campaign)$pdo->prepare('INSERT IGNORE INTO campaign_registrations(campaign_id,driver_id,counted,counted_at,attribution_employee_id,registration_source) VALUES(?,?,?,?,?,?)')->execute([(int)$campaign,$id,$verification==='verified'?1:0,$verification==='verified'?gmdate('Y-m-d H:i:s'):null,$employee,$source?:null]);audit('driver.created','driver',$id,['status'=>$status]);});flash('success','Driver record created successfully.');}catch(Throwable $e){flash('error','Could not save the driver record.');}redirect('drivers.php');
